
DROP TABLE IF EXISTS rapidapi_cache;
CREATE TABLE rapidapi_cache (
  id TEXT PRIMARY KEY,
  slug TEXT,
  category TEXT,
  categorySlug TEXT,
  brand TEXT,
  title TEXT,
  description TEXT,
  basePrice REAL,
  retailPrice REAL,
  stockStatus TEXT,
  image_url TEXT,
  images_json TEXT DEFAULT NULL,
  features_json TEXT DEFAULT NULL
);

